#include "Data/AetherSkillEffectRegistry.h"
#include "Data/AetherContentRegistry.h"
#include "Data/AetherAssetRegistry.h"
namespace { FString N(const FString& S){return S.TrimStartAndEnd();} }
bool FAetherSkillEffectRegistry::IsIDAvailable(const FString& I)const{FString NID=N(I);return !Skills.Contains(NID)&&!Effects.Contains(NID)&&!Statuses.Contains(NID);}
bool FAetherSkillEffectRegistry::RegisterSkill(const FAetherSkillDefinition&D,FString&E){E.Reset();if(!D.IsStructurallyValid(E))return false;FString I=N(D.DefinitionID);if(!IsIDAvailable(I)){E=FString::Printf(TEXT("Duplicate definition ID '%s'."),*I);return false;}auto C=D;C.DefinitionID=I;Skills.Add(I,MoveTemp(C));return true;}
bool FAetherSkillEffectRegistry::RegisterEffect(const FAetherEffectDefinition&D,FString&E){E.Reset();if(!D.IsStructurallyValid(E))return false;FString I=N(D.DefinitionID);if(!IsIDAvailable(I)){E=FString::Printf(TEXT("Duplicate definition ID '%s'."),*I);return false;}auto C=D;C.DefinitionID=I;Effects.Add(I,MoveTemp(C));return true;}
bool FAetherSkillEffectRegistry::RegisterStatus(const FAetherStatusDefinition&D,FString&E){E.Reset();if(!D.IsStructurallyValid(E))return false;FString I=N(D.DefinitionID);if(!IsIDAvailable(I)){E=FString::Printf(TEXT("Duplicate definition ID '%s'."),*I);return false;}auto C=D;C.DefinitionID=I;Statuses.Add(I,MoveTemp(C));return true;}
bool FAetherSkillEffectRegistry::ResolveSkill(const FString&I,FAetherSkillDefinition&O)const{auto*P=Skills.Find(N(I));if(!P)return false;O=*P;return true;}
bool FAetherSkillEffectRegistry::ResolveEffect(const FString&I,FAetherEffectDefinition&O)const{auto*P=Effects.Find(N(I));if(!P)return false;O=*P;return true;}
bool FAetherSkillEffectRegistry::ResolveStatus(const FString&I,FAetherStatusDefinition&O)const{auto*P=Statuses.Find(N(I));if(!P)return false;O=*P;return true;}
bool FAetherSkillEffectRegistry::Contains(const FString&I)const{FString X=N(I);return Skills.Contains(X)||Effects.Contains(X)||Statuses.Contains(X);}
void FAetherSkillEffectRegistry::AddIssue(TArray<FAetherSkillEffectValidationIssue>&O,const FString&I,const FString&C,const FString&M)const{auto&X=O.AddDefaulted_GetRef();X.DefinitionID=I;X.Code=C;X.Message=M;}
bool FAetherSkillEffectRegistry::Validate(TArray<FAetherSkillEffectValidationIssue>&O,const FAetherContentRegistry*CR,const FAetherAssetRegistry*AR)const{O.Reset();bool OK=true;auto Asset=[&](const FString&I){if(AR&&!N(I).IsEmpty()&&!AR->Contains(I)){AddIssue(O,I,TEXT("MissingAssetReference"),TEXT("Referenced asset does not exist."));OK=false;}};auto Effect=[&](const FString&I){if(!Effects.Contains(I)){AddIssue(O,I,TEXT("MissingEffectReference"),TEXT("Referenced effect does not exist."));OK=false;}};auto Content=[&](const FString&I,EAetherContentType T){if(CR){FAetherContentDefinition C;if(!CR->Resolve(I,C)||C.Type!=T){AddIssue(O,I,TEXT("MissingContentDefinition"),TEXT("Missing or wrong content type."));OK=false;}}};for(const auto&K:Skills){const auto&D=K.Value;FString E;if(!D.IsStructurallyValid(E)){AddIssue(O,K.Key,TEXT("InvalidDefinition"),E);OK=false;}Content(K.Key,EAetherContentType::Skill);Asset(D.AnimationAssetID);Asset(D.VisualAssetID);for(const FString&I:D.EffectIDs)Effect(I);}for(const auto&K:Effects){const auto&D=K.Value;FString E;if(!D.IsStructurallyValid(E)){AddIssue(O,K.Key,TEXT("InvalidDefinition"),E);OK=false;}Asset(D.VisualAssetID);for(const FString&I:D.ConflictingEffectIDs)if(!Effects.Contains(I)){AddIssue(O,I,TEXT("MissingConflictingEffect"),TEXT("Conflicting effect does not exist."));OK=false;}}for(const auto&K:Statuses){const auto&D=K.Value;FString E;if(!D.IsStructurallyValid(E)){AddIssue(O,K.Key,TEXT("InvalidDefinition"),E);OK=false;}for(const FString&I:D.EffectIDs)Effect(I);}return OK&&O.Num()==0;}
void FAetherSkillEffectRegistry::GetDefinitionIDs(TArray<FString>&O)const{O.Reset();Skills.GetKeys(O);TArray<FString>X;Effects.GetKeys(X);O.Append(X);Statuses.GetKeys(X);O.Append(X);O.Sort();}
void FAetherSkillEffectRegistry::Reset(){Skills.Reset();Effects.Reset();Statuses.Reset();}
